import React from 'react';import{createRoot}from'react-dom/client';
import{SocialProvider,MessengerTile}from'../../../src/social/SocialContext';import{SocialGlobal}from'../../../src/social/SocialHub';import Discovery,{DiscoveryShortcut}from'../../../src/social/Discovery';import{StorageContext}from'../../../src/StorageContext';import'../../../src/style.css';import'../../../src/design-system.css';import'../../../src/finish.css';import'../../../src/ux-polish.css';
const peer={id:'connection-qa',user_id:'peer-qa',handle:'studio.camille',display_name:'Studio Camille',account_tier:'pro',status:'accepted',unread:1};
const people=[{entity_type:'user',entity_id:'peer-qa',handle:peer.handle,display_name:peer.display_name,kind:'independent',city:'Lyon'},{entity_type:'user',entity_id:'second-qa',handle:'studio.anais',display_name:'Studio Anaïs',kind:'independent',city:'Paris'}];
let relations=[peer],historyCount=0;const messages=[{id:'msg-qa',mine:false,body:'Bonjour, retrouvons ton inspiration ici.',created_at:'2026-09-28T09:00:00Z'}];
const post={id:'post-qa',kind:'journal',title:'Cassis poudré',handle:peer.handle,tags:{colors:['Rose']},saved:false,preview:{shape:'Amande',length:'Moyen',description:'Pose de démonstration',nails:Array.from({length:5},()=>({color:'#813c60',finish:'Brillant'}))}};
const client={auth:{getUser:async()=>({data:{user:{id:'user-qa'}}}),getSession:async()=>({data:{session:null}})},from(table){const q={select(){return q},eq(){return q},is(){return q},order(){return q},limit(){return q},single(){return q},update(){return q},in(){return q},then(resolve){return Promise.resolve({data:table==='profiles'?{username:'marie.qa',display_name:'Marie test',discovery_visibility:'everyone'}:[],count:0}).then(resolve)}};return q},async rpc(name,{p_action:a,p_data:d={},p_handle,p_query}={}){if(name==='nm_social'){if(a==='list')return{data:relations};if(a==='history'){historyCount++;return historyCount===2?{error:{message:'Network unavailable'}}:{data:{messages:[...messages]}};}if(a==='send'){messages.unshift({id:d.client_id,mine:true,body:d.body,created_at:new Date().toISOString()});return{data:{ok:true}};}if(a==='request'){relations=[...relations,{id:'pending-qa',user_id:'second-qa',handle:'studio.anais',display_name:'Studio Anaïs',account_tier:'pro',status:'pending',outgoing:true}];return{data:{outgoing:true}};}return{data:[]};}if(name==='search_nailmoods')return{data:people.filter(p=>[p.display_name,p.handle].join(' ').toLowerCase().includes((p_query||'').replace('@','').toLowerCase()))};if(name==='get_public_profile')return{data:{displayName:people.find(p=>p.handle===p_handle)?.display_name||'Profil test',handle:p_handle,accountType:'independent',journal:[],inspirations:[]}};if(name==='nm_discover'){if(a==='detail')return{data:{...post}};if(a==='add'||a==='remove'){post.saved=a==='add';return{data:{ok:true}};}return{data:{items:[{...post}],hasMore:false}};}return{data:[]};}};
const values=new Map();const storage={getItem:k=>values.get(k)||null,setItem:(k,v)=>values.set(k,v),accountScoped:true,accountTier:'pro',userId:'user-qa',workspaceId:'workspace-qa'};
function Demo(){return<StorageContext.Provider value={storage}><SocialProvider client={client} userId="user-qa" tier="pro"><div className="app phase2"><header><img width="150" src="/nailmoods-official.png" alt="NailMoods"/></header><main style={{padding:20}}><h1>Contrôle UX connecté</h1><p>Données fictives locales. Aucun message ni invitation réels.</p><MessengerTile/><DiscoveryShortcut/><SocialGlobal/><Discovery/></main></div></SocialProvider></StorageContext.Provider>};createRoot(document.getElementById('root')).render(<Demo/>);
